parameters.jsCode:
const cr = $json.body.check_run;
const suite = cr.check_suite;
const urlMatch = (cr.details_url || '').match(/\/actions\/runs\/(\d+)\/job\/(\d+)/);
const branch = suite.head_branch || '';
const linearMatch = branch.match(/^([a-z]+-\d+)/i);

return [{
  json: {
    runId: urlMatch?.[1] ?? null,
    jobId: urlMatch?.[2] ?? null,
    jobName: cr.name,
    branch,
    sha: suite.head_sha,
    shortSha: (suite.head_sha || '').slice(0, 7),
    checkUrl: cr.html_url,
    detailsUrl: cr.details_url,
    linearId: linearMatch?.[1]?.toUpperCase() ?? null,
  },
}];

const meta = $('Extract job + branch').first().json;
const raw = typeof $json.data === 'string' ? $json.data : ($json.body ?? '');
const log = String(raw);

// Strip GH log timestamps like "2025-04-01T10:23:45.1234567Z "
const clean = log.replace(/^\S+T\S+Z\s/gm, '');

// Jest/Vitest patterns
const failFile = clean.match(/FAIL\s+(\S+\.(?:test|spec)\.[tj]sx?)/)?.[1]
  ?? clean.match(/×\s+(\S+\.(?:test|spec)\.[tj]sx?)/)?.[1]
  ?? null;

// First failing test name — Jest uses "●  describe > it", Vitest uses " ✕  describe > it"
const testNameMatch =
  clean.match(/●\s+(.+?)\n/) ??
  clean.match(/✕\s+(.+?)\n/) ??
  clean.match(/FAIL\s+.+\n\s*(.+?)\n/);
const failTest = testNameMatch?.[1]?.trim() ?? null;

// Error block — grab from the first ●/✕ marker, ~25 lines, capped at 1800 chars for Slack
let errSnippet = '';
const markerIdx = clean.search(/[●✕]\s+/);
if (markerIdx >= 0) {
  const slice = clean.substring(markerIdx, markerIdx + 4000);
  errSnippet = slice.split('\n').slice(0, 25).join('\n').slice(0, 1800);
} else {
  // Fallback — find first "Error:" line and surrounding context
  const errIdx = clean.search(/^\s*(Error|AssertionError|TypeError):/m);
  if (errIdx >= 0) {
    errSnippet = clean.substring(errIdx, errIdx + 1500).split('\n').slice(0, 20).join('\n');
  }
}

return [{
  json: {
    ...meta,
    failFile: failFile ?? 'unknown',
    failTest: failTest ?? 'unknown',
    errSnippet: errSnippet || '(no parseable error block — check logs link)',
  },
}];

