        { "type": "mrkdwn", "text": "*Commit:*\n`" + $json.shortSha + "`" },
        { "type": "mrkdwn", "text": "*Test file:*\n`" + $json.failFile + "`" },
        { "type": "mrkdwn", "text": "*Failing test:*\n" + $json.failTest }
      ]
    },
    {
      "type": "section",
      "text": { "type": "mrkdwn", "text": "```\n" + $json.errSnippet + "\n```" }
    },
    {
      "type": "context",
      "elements": [
        { "type": "mrkdwn", "text": "<" + $json.checkUrl + "|Open job logs>" + ($json.linearId ? " • <https://linear.app/n8n/issue/" + $json.linearId + "|" + $json.linearId + ">" : "") }
      ]
    }
  ]
}
